-- ─────────────────────────────────────────────────────────────────
-- Migración 008: Datos reales de operación
-- ─────────────────────────────────────────────────────────────────
-- Generado por validacion/generar_seed.py a partir de 'Presentismo V4.xlsx'
-- y 'Liquidación Honorarios Julio 2026'. No editar a mano: volver a generar.
--
--   3 clientes · 13 agentes · 721 marcaciones
--   65 tramos de esquema · 22 registros de horas extra
--   Marcaciones desde 2026-06-01 hasta 2026-08-18
--
-- Los UUID son determinísticos (uuid5 sobre el nombre), así que la migración
-- es idempotente: correrla dos veces no duplica nada.
--
-- Los agentes se crean SIN contraseña: no pueden iniciar sesión hasta que se
-- los invite desde Supabase. El rol `agent` todavía no tiene pantallas propias
-- y las marcaciones las carga el supervisor, así que no hace falta.
--
-- No se incluye ningún dato sensible (CBU, CUIL, DNI, claves de AFIP) aunque
-- esté en el Excel de origen.
-- ─────────────────────────────────────────────────────────────────

-- ─── Precondiciones ─────────────────────────────────────────────
-- Mejor un error que diga qué falta, que un NOT NULL violation críptico.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_schema='public' AND table_name='agent_rates'
               AND column_name='day_of_week') THEN
    RAISE EXCEPTION 'Falta aplicar la migración 006: agent_rates todavía tiene day_of_week.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                 WHERE table_schema='public' AND table_name='profiles'
                   AND column_name='reg_people_pct') THEN
    RAISE EXCEPTION 'Falta aplicar la migración 007: profiles no tiene los parámetros de liquidación.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                 WHERE table_schema='public' AND table_name='pre_settlement_daily'
                   AND column_name='band') THEN
    RAISE EXCEPTION 'Falta aplicar la migración 007: pre_settlement_daily no tiene band/tier.';
  END IF;
END $$;

-- ─── Clientes ───────────────────────────────────────────────────
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, is_active = EXCLUDED.is_active;

