-- ─── Tarifa base ────────────────────────────────────────────────
-- Todos comparten la misma tarifa base ($4,040.16029), de la hoja
-- 'Valores Horas 31_12_2024'. Los recargos son globales, en `rate_factors`.
ON CONFLICT (id) DO UPDATE SET amount_per_hour = EXCLUDED.amount_per_hour;

-- ─── Esquemas horarios ──────────────────────────────────────────
-- day_of_week sigue la convención de Postgres/JS: 0 = domingo.
-- Los turnos partidos se cargan como dos filas del mismo día.
-- OJO Paola Farías: liquida 9:45 por día contra 9:00 de esquema.
-- OJO María Sol Olaviaga: tres días de cobertura de 8 h sin excepción cargada.
-- OJO Walter Palavecino: liquida 5 h los jueves contra 4 h de esquema.
-- OJO Alanis Brenda: liquidó 6 h el jueves 2 contra 5 h de esquema.
-- OJO Moreno Laura: liquidó 6 h el jueves 2 contra 5 h de esquema.
--     Se carga lo que dice la planilla; el motor lo va a marcar como desvío.
ON CONFLICT (id) DO UPDATE SET
  start_time = EXCLUDED.start_time, end_time = EXCLUDED.end_time,
  client_id = EXCLUDED.client_id;

-- Sin esquema en la planilla de origen, hay que cargarlo a mano:
--   Priscila Ferreyra

-- ─── Feriados ───────────────────────────────────────────────────
ON CONFLICT (date, holiday_type) DO NOTHING;

-- ─── Excepciones ────────────────────────────────────────────────
-- vacation = vacaciones · paid_leave = licencia paga (se liquida) ·
-- absence = ausencia (no se liquida)
DO $$
DECLARE v_creador UUID;
BEGIN
  -- created_by exige un perfil existente; se usa un admin/supervisor.
  SELECT id INTO v_creador FROM profiles
   WHERE role IN ('admin', 'supervisor') ORDER BY created_at LIMIT 1;
  IF v_creador IS NULL THEN
    SELECT id INTO v_creador FROM profiles ORDER BY created_at LIMIT 1;
  END IF;

  ON CONFLICT (id) DO NOTHING;
END $$;

-- ─── Horas adicionales y extra ──────────────────────────────────
-- Tomadas de la grilla de la liquidación de julio 2026 (columnas de
-- extras/adicionales y su etiqueta). Junio no tiene liquidación disponible,
-- así que sus extras habrá que cargarlos a mano.
-- Las que traen nota de arrastre corresponden al cierre del mes anterior;
-- se cargan en la fecha que usó la planilla y la nota queda como referencia.
DO $$
DECLARE v_creador UUID;
BEGIN
  SELECT id INTO v_creador FROM profiles
   WHERE role IN ('admin', 'supervisor') ORDER BY created_at LIMIT 1;
  IF v_creador IS NULL THEN
    SELECT id INTO v_creador FROM profiles ORDER BY created_at LIMIT 1;
  END IF;

  ON CONFLICT (id) DO UPDATE SET hours = EXCLUDED.hours, tier = EXCLUDED.tier;
END $$;

-- ─── Marcaciones ────────────────────────────────────────────────
-- Ingresos y egresos reales de 'Respuestas presentismo', apareados por orden
-- cronológico. Un día puede tener más de una jornada (turno partido).
ON CONFLICT (id) DO UPDATE SET
  clock_in = EXCLUDED.clock_in, clock_out = EXCLUDED.clock_out;

